def isValid(code):
    n = len(code)
    if n == 0 or code[0] != '<':
        return False
    stack = []
    i = 0
    while i < n:
        if code[i] == '<':
            if i + 1 < n and code[i + 1] == '!':
                if not stack:
                    return False
                if code[i:i + 9] != '<![CDATA[':
                    return False
                end = code.find(']]>', i + 9)
                if end == -1:
                    return False
                i = end + 3
                continue
            elif i + 1 < n and code[i + 1] == '/':
                j = code.find('>', i + 2)
                if j == -1:
                    return False
                name = code[i + 2:j]
                if not (1 <= len(name) <= 9 and name.isupper() and name.isalpha()):
                    return False
                if not stack or stack[-1] != name:
                    return False
                stack.pop()
                i = j + 1
                if not stack and i != n:
                    return False
                continue
            else:
                j = code.find('>', i + 1)
                if j == -1:
                    return False
                name = code[i + 1:j]
                if not (1 <= len(name) <= 9 and name.isupper() and name.isalpha()):
                    return False
                stack.append(name)
                i = j + 1
                continue
        else:
            if not stack:
                return False
            i += 1
    return len(stack) == 0
